document.documentElement.classList.add('js-ready');
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
let paused = reduceMotion.matches, phase = 0, topology = 'star', autoTimer = null;
const phases = [
  {rtt:6.0508,goodput:9.2999,color:'#c5c5c5',status:'PHASE 01 / BASELINE',note:'Reference conditions. Traffic flows under stable network settings.'},
  {rtt:32.8780,goodput:1.9001,color:'#c0c0c0',status:'PHASE 02 / CONSTRAINED',note:'Constrained conditions. Measured RTT rises as TCP goodput falls.'},
  {rtt:6.2758,goodput:9.2628,color:'#cacaca',status:'PHASE 03 / RECOVERY',note:'Reference settings restored. Measured behavior returns toward baseline.'}
];
const observer = new IntersectionObserver(entries => { entries.forEach(entry => { if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target);} }); },{threshold:.08});
$$('.reveal').forEach(el => observer.observe(el));
function updateProgress(){const h = document.documentElement;$('#progress').style.width = (h.scrollHeight>innerHeight ? scrollY/(h.scrollHeight-innerHeight)*100 : 0)+'%';}
addEventListener('scroll',updateProgress,{passive:true});updateProgress();
$('#menu').addEventListener('click',()=>{const open=$('nav').classList.toggle('open');$('#menu').setAttribute('aria-expanded',open);$('#menu').setAttribute('aria-label',open?'Close navigation':'Open navigation');});
$$('nav a').forEach(a=>a.addEventListener('click',()=>{$('nav').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}));
function setPhase(index){phase=index;const p=phases[index];document.documentElement.style.setProperty('--phase',p.color);$('#rtt').textContent=p.rtt.toFixed(4);$('#goodput').textContent=p.goodput.toFixed(4);$('#rtt-meter').style.width=(p.rtt/40*100)+'%';$('#goodput-meter').style.width=(p.goodput/10*100)+'%';$('#phase-status').textContent=p.status;$('#phase-note').textContent=p.note;$$('[data-phase]').forEach(b=>{const active=Number(b.dataset.phase)===index;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});}
function stopAuto(){clearInterval(autoTimer);autoTimer=null;$('#play').textContent='▶ Auto-play';$('#play').setAttribute('aria-pressed','false');}
$$('[data-phase]').forEach(b=>b.addEventListener('click',()=>{stopAuto();setPhase(Number(b.dataset.phase));}));
$('#play').addEventListener('click',()=>{if(autoTimer){stopAuto();return;}$('#play').textContent='Ⅱ Pause cycle';$('#play').setAttribute('aria-pressed','true');setPhase((phase+1)%3);autoTimer=setInterval(()=>setPhase((phase+1)%3),3200);});
function setMotion(value){paused=value;document.documentElement.classList.toggle('motion-paused',paused);$('#motion').setAttribute('aria-pressed',paused);$('#motion').setAttribute('aria-label',paused?'Resume decorative animations':'Pause decorative animations');$('#motion').textContent=paused?'▶ Motion':'Ⅱ Motion';if(paused)stopAuto();}
$('#motion').addEventListener('click',()=>setMotion(!paused));reduceMotion.addEventListener('change',e=>setMotion(e.matches));setMotion(paused);
let topologyEdges=[];
function drawTopology(){const star=[{x:300,y:145,l:'OVS · S1',type:'switch'},{x:130,y:70,l:'HOST 01'},{x:470,y:70,l:'HOST 02'},{x:130,y:230,l:'HOST 03'},{x:470,y:230,l:'HOST 04'},{x:300,y:35,l:'RYU',type:'controller'}];const line=[{x:110,y:145,l:'OVS · S1',type:'switch'},{x:300,y:145,l:'OVS · S2',type:'switch'},{x:490,y:145,l:'OVS · S3',type:'switch'},{x:110,y:245,l:'HOST 01'},{x:300,y:245,l:'HOST 02'},{x:490,y:245,l:'HOST 03'},{x:300,y:35,l:'RYU',type:'controller'}];const n=topology==='star'?star:line;const e=topology==='star'?[[0,1],[0,2],[0,3],[0,4],[5,0]]:[[0,1],[1,2],[0,3],[1,4],[2,5],[6,0],[6,1],[6,2]];topologyEdges=e.map(([a,b])=>[n[a],n[b]]);$('#links').innerHTML=topologyEdges.map(([a,b],i)=>`<line class="topology-link" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" ${a.type==='controller'?'stroke-dasharray="4 5"':''}/><circle class="packet" data-packet="${i}" r="2.5" cx="${a.x}" cy="${a.y}"/>`).join('');$('#nodes').innerHTML=n.map(a=>`<g transform="translate(${a.x},${a.y})"><rect class="node-box" x="-25" y="-20" width="50" height="40" rx="5"/><text class="node-symbol" text-anchor="middle" y="7">${a.type==='controller'?'⌘':a.type==='switch'?'≋':'▱'}</text><text class="node-label" text-anchor="middle" y="37">${a.l}</text></g>`).join('');$('#topology').setAttribute('aria-label',`Illustrative ${topology} SDN topology with Ryu controller`);}
$$('[data-topology]').forEach(b=>b.addEventListener('click',()=>{topology=b.dataset.topology;$$('[data-topology]').forEach(a=>{const active=a===b;a.classList.toggle('active',active);a.setAttribute('aria-pressed',active);});drawTopology();}));
const scenarios=[
  ['B00','BENIGN WORKLOAD','The everyday baseline.','Continuous UDP and ICMP communication represents normal network activity. Its observations provide context across changing network conditions.','Activity labels follow recorded workload intervals. Network constraints are tracked separately from benign activity.'],
  ['B01','BENIGN WORKLOAD','A burst is not an attack.','Authorized UDP traffic bursts represent legitimate increases in traffic intensity. Higher traffic alone does not justify a security label.','Execution logs identify authorized workload intervals. Benign bursts stay distinct from synthetic security activity.'],
  ['A01','SYNTHETIC WORKLOAD','Bounded reconnaissance.','TCP probing within a limited port range generates a controlled reconnaissance-like workload inside the isolated SDN testbed.','Generator-level execution evidence confirms traffic generation. It does not establish attack success or independently verified malicious activity.'],
  ['A02','SYNTHETIC WORKLOAD','Elevated, under control.','A controlled increase in UDP traffic introduces a synthetic security-relevant workload, separate from the network-condition phase.','Generator-level evidence documents workload execution. Increased traffic is not independently verified evidence of a successful malicious attack.'],
  ['A03','SYNTHETIC WORKLOAD','Connections in motion.','Repeated TCP connection establishment and tear-down create controlled connection churn across the network phases.','The paper reports endpoint-level verification for this scenario. Independent malicious ground-truth adjudication remains incomplete.'],
  ['A04','SYNTHETIC WORKLOAD','Small signals. Clear context.','Low-rate TCP probing targets a controlled service, exploring synthetic activity that is different from a high-volume traffic burst.','The paper reports endpoint-level verification. Synthetic probing labels do not establish detection of real-world or unseen malicious attack families.']
];
function setScenario(i){const s=scenarios[i];$('#scenario-code').textContent=s[0];$('#scenario-category').textContent=s[1];$('#scenario-title').textContent=s[2];$('#scenario-description').textContent=s[3];$('#scenario-evidence').textContent=s[4];$$('[data-scenario]').forEach(b=>{const active=Number(b.dataset.scenario)===i;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('.wave').innerHTML=Array.from({length:44},(_,j)=>{let h=i===1||i===3?18+(Math.sin(j*.8)**2)*52:i===4?10+(j%4)*17:i===5?8+(j%11===0?55:4):15+Math.sin(j*.45)**2*35;return `<i style="height:${h}px;animation-delay:${-j*.13}s;animation-duration:${1.1+(j%7)*.17}s"></i>`;}).join('');}
$$('[data-scenario]').forEach(b=>b.addEventListener('click',()=>setScenario(Number(b.dataset.scenario))));
const models=[{name:'Logistic Regression',ba:.6250,recall:.5833,fpr:.3333},{name:'Random Forest',ba:.8875,recall:.8750,fpr:.1000},{name:'RBF-SVM',ba:.5000,recall:0,fpr:0},{name:'Gradient Boosting',ba:.8958,recall:.7917,fpr:0},{name:'Soft Voting Ensemble',ba:.8750,recall:.7500,fpr:0}];
function renderChart(){const metric=$('#chart-metric').value;const best=metric==='fpr'?Math.min(...models.map(m=>m[metric])):Math.max(...models.map(m=>m[metric]));$('#model-chart').innerHTML=models.map(m=>`<div class="chart-row ${m[metric]===best?'best':''}"><span>${m.name}</span><div class="chart-track"><div class="chart-bar" style="width:${m[metric]*100}%"></div></div><strong>${(m[metric]*100).toFixed(2)}%</strong></div>`).join('');}
$('#chart-metric').addEventListener('change',renderChart);
const canvas=$('#network'),ctx=canvas.getContext('2d');let cw=0,ch=0;
function resizeCanvas(){const rect=canvas.getBoundingClientRect();cw=rect.width;ch=rect.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=cw*dpr;canvas.height=ch*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);}
new ResizeObserver(resizeCanvas).observe(canvas);
const globeNodes=Array.from({length:64},(_,i)=>{const y=1-(i/63)*2,r=Math.sqrt(1-y*y),angle=2.399963229728653*i;return{x:Math.cos(angle)*r,y,z:Math.sin(angle)*r};});
const globeEdges=[];globeNodes.forEach((a,i)=>globeNodes.forEach((b,j)=>{if(j>i&&Math.hypot(a.x-b.x,a.y-b.y,a.z-b.z)<.54)globeEdges.push([i,j]);}));
let elapsed=0,lastFrame=0;
function frame(now){const dt=lastFrame?Math.min(now-lastFrame,50):0;lastFrame=now;if(!paused&&!document.hidden)elapsed+=dt;drawGlobe(elapsed*.00012);if(!paused){$$('[data-packet]').forEach((p,i)=>{const edge=topologyEdges[i];if(!edge)return;const t=(elapsed/(phase===1?4500:1900)+i*.17)%1;p.setAttribute('cx',edge[0].x+(edge[1].x-edge[0].x)*t);p.setAttribute('cy',edge[0].y+(edge[1].y-edge[0].y)*t);});}requestAnimationFrame(frame);}
function drawGlobe(t){if(!cw||!ch)return;ctx.clearRect(0,0,cw,ch);const cx=cw*.53,cy=ch*.48,r=Math.min(cw*.36,ch*.36);ctx.strokeStyle='#5e5e5e55';ctx.lineWidth=.6;for(let ring=0;ring<3;ring++){ctx.beginPath();ctx.ellipse(cx,cy,r*(1.15+ring*.12),r*(.42+ring*.02),-.28+ring*.2,0,Math.PI*2);ctx.stroke();}ctx.save();ctx.translate(cx,cy);ctx.rotate(-.18);ctx.strokeStyle='#c5c5c513';for(let j=0;j<2;j++){ctx.beginPath();ctx.ellipse(0,0,r*1.04,r*1.04,0,0,Math.PI*2);ctx.stroke();}ctx.restore();const projected=globeNodes.map(n=>{const x=n.x*Math.cos(t)+n.z*Math.sin(t),z=-n.x*Math.sin(t)+n.z*Math.cos(t);const tilt=.22;return{x:cx+x*r,y:cy+(n.y*Math.cos(tilt)-z*Math.sin(tilt))*r,z:n.y*Math.sin(tilt)+z*Math.cos(tilt)};});globeEdges.forEach(([i,j],k)=>{const a=projected[i],b=projected[j],depth=(a.z+b.z+2)/4;ctx.strokeStyle=`rgba(186,186,186,${.08+depth*.26})`;ctx.lineWidth=.6+depth*.5;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();if(k%5===0){const p=(elapsed*.00016+k*.137)%1;ctx.fillStyle=`rgba(238,238,238,${.25+depth*.7})`;ctx.beginPath();ctx.arc(a.x+(b.x-a.x)*p,a.y+(b.y-a.y)*p,1.4,0,Math.PI*2);ctx.fill();}});projected.forEach((n,i)=>{const a=(n.z+1)/2;ctx.fillStyle=`rgba(220,220,220,${.2+a*.8})`;ctx.beginPath();ctx.arc(n.x,n.y,1.4+a*2,0,Math.PI*2);ctx.fill();if(i%12===0&&n.z>-.2){ctx.strokeStyle='#c5c5c555';ctx.strokeRect(n.x-6,n.y-6,12,12);ctx.fillStyle='#d2d2d2';ctx.font='7px monospace';ctx.fillText('S'+String(i+1).padStart(2,'0'),n.x+10,n.y+3);}});ctx.fillStyle='#c4c4c4';ctx.font='8px monospace';ctx.fillText('SDN / VIRTUAL FABRIC',cx-r*.7,cy+r+37);}
setPhase(0);setScenario(0);drawTopology();renderChart();requestAnimationFrame(frame);
